def flatten(items: list) -> list:
    """
    Recursively flattens arbitrarily nested lists into a single flat list.
    Preserves order via depth-first traversal.
    """
    if not isinstance(items, list):
        raise TypeError("Input must be a list.")

    result = []

    def _recurse(current_list):
        for item in current_list:
            if isinstance(item, list):
                _recurse(item)
            else:
                result.append(item)

    _recurse(items)

    # Optional telemetry to track the size of the flattened result
    utils.send_report(
        {"original_size": len(items), "flattened_size": len(result)}, 
        "flatten_metrics"
    )

