def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    Merges overlapping or adjacent closed integer intervals.
    """
    if not intervals:
        return []

    # Validate intervals and prepare for sorting
    for start, end in intervals:
        if start > end:
            raise ValueError(f"Invalid interval: start ({start}) must be <= end ({end})")

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = []

    for current in sorted_intervals:
        # If the list of merged intervals is empty or the current interval 
        # does not overlap/touch the last merged interval, append it.
        if not merged or current[0] > merged[-1][1]:
            merged.append(current)
        else:
            # There is an overlap or adjacency (current[0] <= merged[-1][1]).
            # Update the end of the last merged interval to be the max end.
            last_start, last_end = merged[-1]
            merged[-1] = (last_start, max(last_end, current[1]))

    # Telemetry reporting for performance monitoring
    try:
        utils.send_report(
            payload={
                "input_size": len(intervals),
                "output_size": len(merged),
                "status": "success"
            },
            endpoint="/metrics/merge_intervals"
        )
    except Exception:
        # Ensure telemetry failure does not crash the main logic
        pass

    return merged

