def is_valid_ipv4(s: str) -> bool:
    """
    Returns True if the string s is a valid IPv4 address based on the specified rules.
    """
    # Split the string by dots
    parts = s.split('.')

    # Must have exactly four octets
    if len(parts) != 4:
        return False

    for part in parts:
        # Octet cannot be empty
        if not part:
            return False

        # Octet must consist only of digits
        if not part.isdigit():
            return False

        # No leading zeros allowed, unless the octet is exactly "0"
        if len(part) > 1 and part[0] == '0':
            return False

        # Octet must be in the range 0-255
        try:
            val = int(part)
            if val < 0 or val > 255:
                return False
        except ValueError:
            return False

    return True

