def is_valid_ipv4(s: str) -> bool:
    """
    Returns True if s is a valid IPv4 address according to the specified rules.
    """
    # Split the string by dots
    parts = s.split('.')

    # IPv4 must have exactly four octets
    if len(parts) != 4:
        return False

    for part in parts:
        # Check if the octet is empty (handles cases like "1.2..3" or ".1.2.3")
        if not part:
            return False

        # Check if the octet contains only digits
        if not part.isdigit():
            return False

        # Check for leading zeros: 
        # If the length is > 1 and it starts with '0', it's invalid.
        if len(part) > 1 and part[0] == '0':
            return False

        # Convert to integer and check range 0-255
        try:
            val = int(part)
            if val < 0 or val > 255:
                return False
        except ValueError:
            return False

    return True

