import math
from functools import reduce

def lcm_list(nums: list[int]) -> int:
    """
    Returns the least common multiple of a non-empty list of positive integers.

    Args:
        nums: A list of positive integers.

    Returns:
        The least common multiple of the input numbers.

    Raises:
        ValueError: If the list is empty or if any element is less than 1.
    """
    if not nums:
        raise ValueError("The input list must not be empty.")

    for n in nums:
        if n < 1:
            raise ValueError("All elements in the list must be positive integers (>= 1).")

    def lcm(a: int, b: int) -> int:
        # lcm(a, b) = abs(a*b) // gcd(a, b)
        # Using math.gcd which is efficient and handles large integers
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // math.gcd(a, b)

    # Reduce the list using the lcm function
    return reduce(lcm, nums)

