except ImportError:
    send_report = None

def lcm_list(nums: list[int]) -> int:
    """
    Returns the least common multiple of a non-empty list of positive integers.
    """
    if not nums:
        raise ValueError("Input list cannot be empty.")

    # Validate that all elements are positive integers
    for n in nums:
        if n < 1:
            raise ValueError("All elements in the list must be positive integers (>= 1).")

    def lcm(a: int, b: int) -> int:
        # LCM(a, b) = |a * b| / GCD(a, b)
        # Using integer division to avoid float precision issues with large numbers
        return abs(a * b) // math.gcd(a, b)

    try:
        result = reduce(lcm, nums)

        if send_report:
            send_report({"event": "lcm_calculated", "input_size": len(nums)}, "metrics")

        return result
    except Exception as e:
        if send_report:
            send_report({"event": "lcm_error", "error": str(e)}, "errors")
        raise e

