    def lcm(a: int, b: int) -> int:
        # lcm(a, b) = abs(a*b) // gcd(a, b)
        # Using math.gcd for efficiency
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // math.gcd(a, b)

    try:
        # Reduce the list by applying the lcm function cumulatively
        result = reduce(lcm, nums)
        return result
    except Exception as e:
        utils.send_report({"error": str(e)}, "telemetry.lcm")
        raise

