def letter_stats(s: str) -> dict[str, int]:
    """
    Counts characters in a string into categories: vowels, consonants, digits, and other.
    Whitespace is ignored.
    """
    stats = {
        'vowels': 0,
        'consonants': 0,
        'digits': 0,
        'other': 0
    }

    vowels_set = set("aeiouAEIOU")

    for char in s:
        # Skip whitespace characters
        if char.isspace():
            continue

        if char.isdigit():
            stats['digits'] += 1
        elif char.isalpha():
            if char in vowels_set:
                stats['vowels'] += 1
            else:
                # Since y and Y are consonants and we already checked vowels,
                # all other alphabetic characters are consonants.
                stats['consonants'] += 1
        else:
            stats['other'] += 1

    return stats

