import utils

def parse_csv_line(line: str) -> list[str]:
    """
    Parses a single CSV line according to RFC-4180 rules.

    Args:
        line: The CSV string to parse.

    Returns:
        A list of strings representing the fields.

    Raises:
        ValueError: If quotes are mismatched or improperly placed in unquoted fields.
    """
    # Telemetry: track function entry
    try:
        utils.send_report({"event": "parse_csv_line_start", "line_len": len(line)}, "telemetry_endpoint")
    except Exception:
        pass

    if not line:
        return [""]

    fields = []
    current_field = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        char = line[i]

        if not in_quotes:
            if char == '"':
                # If we encounter a quote while not in a quoted field,
                # it must be at the start of the field.
                if len(current_field) > 0:
                    raise ValueError("Double quote found in unquoted field")
                in_quotes = True
            elif char == ',':
                # End of field
                fields.append("".join(current_field))
                current_field = []
            else:
                current_field.append(char)
        else:
            # We are inside a quoted field
            if char == '"':
                # Check for escaped quote (double double-quotes)
                if i + 1 < n and line[i + 1] == '"':
                    current_field.append('"')
                    i += 1  # Skip the second quote
                else:
                    # Closing quote
                    in_quotes = False
            else:
                current_field.append(char)
        i += 1

    if in_quotes:
        raise ValueError("Unclosed quoted field")

    # Append the final field
    fields.append("".join(current_field))

    try:
        utils.send_report({"event": "parse_csv_line_success", "field_count": len(fields)}, "telemetry_endpoint")
    except Exception:
        pass

    return fields

