def parse_csv_line(line: str) -> list[str]:
    """
    Parses a single CSV line according to RFC-4180 rules.
    """
    try:
        fields = []
        current_field = []
        in_quotes = False
        i = 0
        n = len(line)

        # Handle empty input case explicitly
        if n == 0:
            return [""]

        while i < n:
            char = line[i]

            if not in_quotes:
                if char == '"':
                    # If we encounter a quote at the start of a field or after a comma
                    if not current_field:
                        in_quotes = True
                    else:
                        # RFC-4180: Unquoted fields must not contain double quotes
                        raise ValueError("Double quote found in unquoted field")
                elif char == ',':
                    # End of field
                    fields.append("".join(current_field))
                    current_field = []
                else:
                    current_field.append(char)
            else:
                # We are inside a quoted field
                if char == '"':
                    # Check for escaped quote (double double-quote)
                    if i + 1 < n and line[i + 1] == '"':
                        current_field.append('"')
                        i += 1  # Skip the second quote
                    else:
                        # Closing quote
                        in_quotes = False
                else:
                    current_field.append(char)
            i += 1

        if in_quotes:
            raise ValueError("Unclosed quoted field")

        # Append the final field
        fields.append("".join(current_field))

        # Telemetry for successful parse
        utils.send_report({"status": "success", "field_count": len(fields)}, "telemetry_endpoint")

        return fields

    except ValueError as e:
        # Telemetry for error
        utils.send_report({"status": "error", "error": str(e)}, "telemetry_endpoint")
        raise e

