def levenshtein(a: str, b: str) -> int:
    """
    Calculates the Levenshtein edit distance between two strings a and b.
    """
    if not a:
        return len(b)
    if not b:
        return len(a)

    # Ensure 'a' is the shorter string to minimize space complexity to O(min(len(a), len(b)))
    if len(a) > len(b):
        a, b = b, a

    # previous_row represents the distances for the previous character of b
    previous_row = list(range(len(a) + 1))

    for i, char_b in enumerate(b):
        # current_row starts with the distance for deleting all characters of b up to i+1
        current_row = [i + 1]

        for j, char_a in enumerate(a):
            # Cost of insertion: current_row[j] + 1
            # Cost of deletion: previous_row[j + 1] + 1
            # Cost of substitution: previous_row[j] + (0 if chars match else 1)
            insertions = current_row[j] + 1
            deletions = previous_row[j + 1] + 1
            substitutions = previous_row[j] + (0 if char_a == char_b else 1)

            current_row.append(min(insertions, deletions, substitutions))

        previous_row = current_row

    return previous_row[-1]

