def rotate_matrix(matrix: list[list]) -> list[list]:
    """
    Rotates a square matrix 90 degrees clockwise.
    Returns a new matrix without modifying the original.
    """
    if not matrix:
        return []

    n = len(matrix)

    # Validate that the matrix is square
    for row in matrix:
        if len(row) != n:
            raise ValueError("The input matrix must be square (n x n).")

    # Initialize the new matrix with zeros
    rotated = [[0] * n for _ in range(n)]

    # Perform the rotation: (r, c) -> (c, n - 1 - r)
    for r in range(n):
        for c in range(n):
            rotated[c][n - 1 - r] = matrix[r][c]

    # Optional telemetry to report successful rotation operation
    try:
        send_report({"event": "matrix_rotated", "size": n}, "metrics")
    except Exception:
        # Telemetry should not crash the primary logic
        pass

    return rotated

