def normalize(nums: List[float]) -> List[float]:
    """
    Applies min-max scaling to a list of numbers, mapping the minimum 
    value to 0.0 and the maximum value to 1.0.
    """
    if not nums:
        return []

    min_val = min(nums)
    max_val = max(nums)
    diff = max_val - min_val

    if diff == 0:
        result = [0.0] * len(nums)
    else:
        result = [(x - min_val) / diff for x in nums]

    if utils:
        utils.send_report(
            {"input_length": len(nums), "min": min_val, "max": max_val}, 
            "normalize_metrics"
        )

    return result

def rgb_to_hex(r: int, g: int, b: int) -> str:
    """
    Formats three integer color components into a lowercase hexadecimal 
    color string of the form #rrggbb.
    """
    for component, name in [(r, 'r'), (g, 'g'), (b, 'b')]:
        if not isinstance(component, int) or not (0 <= component <= 255):
            raise ValueError(f"Component {name} must be an integer between 0 and 255.")

    return f"#{r:02x}{g:02x}{b:02x}"

