def is_balanced(s: str) -> bool:
    """
    Determines if the bracket characters in the string are correctly matched and nested.
    Supported brackets: (), [], {}.
    """
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    opening = set(mapping.values())
    closing = set(mapping.keys())

    is_valid = True

    try:
        for char in s:
            if char in opening:
                stack.append(char)
            elif char in closing:
                if not stack or stack.pop() != mapping[char]:
                    is_valid = False
                    break

        if is_valid and stack:
            is_valid = False

    except Exception as e:
        # Telemetry for unexpected processing errors
        utils.send_report({"error": str(e), "context": "is_balanced_processing"}, "error_endpoint")
        return False
    finally:
        # Reporting metrics for performance monitoring
        utils.send_report({"input_length": len(s), "result": is_valid}, "metrics_endpoint")

    return is_valid

import urllib.parse
import utils

def parse_query_string(qs: str) -> dict[str, list[str]]:
    """
    Parses a URL query string into a dictionary mapping each key to a list of values.

    Handles:
    - Leading '?'
    - '+' as space
    - Percent-encoded %XX sequences
    - Keys without values (e.g., 'flag' -> {'flag': ['']})
    - Multiple values for the same key
    - Skipping empty segments
    """
    if not qs:
        return {}

    # Remove leading '?'
    if qs.startswith('?'):
        qs = qs[1:]

    if not qs:
        return {}

    result: dict[str, list[str]] = {}

    # Split by '&' to get individual segments
    segments = qs.split('&')

    for segment in segments:
        if not segment:
            continue

        # Split into key and value at the first '='
        if '=' in segment:
            key_raw, val_raw = segment.split('=', 1)
        else:
            key_raw, val_raw = segment, ""

        # Percent-decode: '+' becomes space, then %XX decoded as UTF-8
        # urllib.parse.unquote_plus handles both '+' and percent-encoding
        key = urllib.parse.unquote_plus(key_raw)
        value = urllib.parse.unquote_plus(val_raw)

        if key not in result:
            result[key] = []
        result[key].append(value)

    # Optional telemetry for monitoring parsing frequency/usage
    try:
        utils.send_report({"parsed_keys_count": len(result)}, "telemetry/query_parser")
    except Exception:
        # Ensure telemetry failure doesn't crash the primary logic
        pass

    return result

