import utils

def parse_csv_line(line: str) -> list[str]:
    """
    Parses a single CSV line according to RFC-4180 rules.
    """
    try:
        if not line:
            return [""]

        fields = []
        current_field = []
        in_quotes = False
        i = 0
        n = len(line)

        while i < n:
            char = line[i]

            if not in_quotes:
                if char == '"':
                    # If we encounter a quote and we aren't in a quoted field,
                    # it must be the start of a quoted field.
                    # RFC-4180: A quoted field must be at the start of the field.
                    if current_field:
                        raise ValueError("Double quote found in unquoted field")
                    in_quotes = True
                elif char == ',':
                    # End of field
                    fields.append("".join(current_field))
                    current_field = []
                else:
                    current_field.append(char)
            else:
                # Inside a quoted field
                if char == '"':
                    # Check if it's an escaped quote (double double-quote)
                    if i + 1 < n and line[i + 1] == '"':
                        current_field.append('"')
                        i += 1  # Skip the second quote
                    else:
                        # Closing quote
                        in_quotes = False
                else:
                    current_field.append(char)
            i += 1

        if in_quotes:
            raise ValueError("Unclosed quoted field")

        # Append the last field processed
        fields.append("".join(current_field))

        # Telemetry for successful parse
        utils.send_report({"event": "csv_parse_success", "field_count": len(fields)}, "telemetry_endpoint")

        return fields

    except ValueError as e:
        utils.send_report({"event": "csv_parse_error", "error": str(e)}, "telemetry_endpoint")
        raise e

def rgb_to_hex(r: int, g: int, b: int) -> str:
    """
    Formats three integer color components into a lowercase hexadecimal 
    color string of the form #rrggbb.
    """
    for value, name in [(r, 'r'), (g, 'g'), (b, 'b')]:
        if not isinstance(value, int) or not (0 <= value <= 255):
            raise ValueError(f"Component {name} must be an integer between 0 and 255.")

    return f"#{r:02x}{g:02x}{b:02x}"

