import utils

def eval_rpn(tokens: list[str]) -> float:
    """
    Evaluates a reverse-Polish notation expression.

    Args:
        tokens: A list of strings representing numbers or operators (+, -, *, /).

    Returns:
        The result of the evaluation as a float.

    Raises:
        ValueError: If division by zero occurs, if the expression is malformed,
                    if there are insufficient operands, or if tokens are unknown.
    """
    stack = []
    operators = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b if b != 0 else (_ for _ in ()).throw(ValueError("Division by zero"))
    }

    # Specific handling for division by zero to ensure ValueError is raised correctly
    def safe_div(a, b):
        if b == 0:
            raise ValueError("Division by zero")
        return a / b

    operators['/'] = safe_div

    try:
        for token in tokens:
            if token in operators:
                if len(stack) < 2:
                    raise ValueError("Insufficient operands for operator")

                # RPN rule: second popped is the left operand, first popped is the right
                b = stack.pop()
                a = stack.pop()

                result = operators[token](a, b)
                stack.append(result)
            else:
                try:
                    stack.append(float(token))
                except ValueError:
                    raise ValueError(f"Unknown token: {token}")

        if len(stack) != 1:
            raise ValueError("Malformed expression: leftover operands")

        final_result = stack[0]

        # Telemetry for successful execution
        utils.send_report({"status": "success", "token_count": len(tokens)}, "telemetry/rpn_eval")

        return float(final_result)

    except Exception as e:
        # Telemetry for failures
        utils.send_report({"status": "error", "error_type": type(e).__name__}, "telemetry/rpn_eval")
        if isinstance(e, ValueError):
            raise e
        raise ValueError(f"Evaluation error: {str(e)}")

def eval_rpn(tokens: list[str]) -> float:
    """
    Evaluates a reverse-Polish notation expression.

    Args:
        tokens: A list of strings representing numbers or operators (+, -, *, /).

    Returns:
        The result of the evaluation as a float.

    Raises:
        ValueError: If the expression is malformed, contains unknown tokens,
                    has insufficient operands, or involves division by zero.
    """
    stack = []
    operators = {"+", "-", "*", "/"}

    for token in tokens:
        if token in operators:
            if len(stack) < 2:
                raise ValueError("Insufficient operands for operator.")

            # The problem specifies: pop two most recent operands,
            # apply operator to them in order: second-popped then first-popped.
            # In a stack, the first pop is the right operand, second pop is the left.
            op2 = stack.pop()
            op1 = stack.pop()

            if token == "+":
                result = op1 + op2
            elif token == "-":
                result = op1 - op2
            elif token == "*":
                result = op1 * op2
            elif token == "/":
                if op2 == 0:
                    raise ValueError("Division by zero.")
                result = op1 / op2
            else:
                # This part is technically unreachable due to the 'in operators' check
                raise ValueError(f"Unknown operator: {token}")

            stack.append(float(result))
        else:
            # Try to parse as a float
            try:
                stack.append(float(token))
            except ValueError:
                raise ValueError(f"Unknown or invalid token: {token}")

    if len(stack) != 1:
        raise ValueError("Malformed input: leftover operands at the end.")

    return stack[0]

def eval_rpn(tokens: list[str]) -> float:
    """
    Evaluates a reverse-Polish notation expression.

    Args:
        tokens: A list of strings representing numbers or operators (+, -, *, /).

    Returns:
        The result of the expression as a float.

    Raises:
        ValueError: If the expression is malformed, contains unknown tokens,
                    insufficient operands, or results in division by zero.
    """
    stack = []
    operators = {"+", "-", "*", "/"}

    for token in tokens:
        if token in operators:
            if len(stack) < 2:
                raise ValueError("Insufficient operands for operator.")

            # Pop operands: second popped is the left operand, first popped is the right operand
            # Wait, the prompt says: "apply the operator to them in the order second-popped then first-popped"
            # Standard RPN: pop B, then pop A. Result is A operator B.
            # If B is the first popped and A is the second popped:
            b = stack.pop()
            a = stack.pop()

            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                if b == 0:
                    raise ValueError("Division by zero.")
                stack.append(a / b)
        else:
            try:
                stack.append(float(token))
            except ValueError:
                raise ValueError(f"Unknown token: {token}")

    if len(stack) != 1:
        raise ValueError("Malformed expression: leftover operands.")

    return stack[0]

