    try:
        for token in tokens:
            if token in operators:
                if len(stack) < 2:
                    raise ValueError("Insufficient operands for operator.")

                # Pop the two most recent operands
                # Order: second-popped is the left operand, first-popped is the right operand
                right = stack.pop()
                left = stack.pop()

                if token == "+":
                    stack.append(left + right)
                elif token == "-":
                    stack.append(left - right)
                elif token == "*":
                    stack.append(left * right)
                elif token == "/":
                    if right == 0:
                        raise ValueError("Division by zero.")
                    stack.append(left / right)
            else:
